import java.util.Arrays

class AvoidMultipleConcatStatementsKt {
    fun testMultipleConcatDefect() {
        var logStatement = ""
        val values = Arrays.asList(*arrayOf("tic", "tac", "toe"))
        logStatement += values[0]
        logStatement += values[1] // bad 8
    }

    fun testMultipleConcatCorrect() {
        var log = 0
        val values = listOf(1, 2, 3)
        log += values[0]
        log += values[1]
    }

    fun testMultipleConcatDefect2() {
        var logStatement = ""
        val values = listOf("tic", "tac", "toe")
        logStatement = logStatement + values[0]
        logStatement = logStatement + values[1] // bad 22
    }

    fun testMultipleConcatCorrect2() {
        var log = 0
        val values = arrayOf(1, 2, 3)
        log = log + values[0]
        log = log + values[1]
    }

    fun testMultipleConcatDefect3() {
        var logStatement = "info: "
        val values = listOf("tic", "tac", "toe")
        logStatement += 2
        logStatement += values[1] // bad 36
    }

    fun testMultipleConcatCorrect3() {
        var log = 0
        val values = listOf(1, 2, 3)
        log += 2
        log += values[1]
    }

    fun testMultipleConcatDefect4() {
        var log = ""
        var i = 0
        val values = listOf(1, 2, 3)
        while (i++ < 3) {
            log = log + values[0]
            log = log + values[1] // bad 51
        }
    }

    fun testMultipleConcatCorrect4() {
        var log = 0
        var i = 0
        while (i++ < 3) {
            val values = listOf(1, 2, 3)
            log = log + values[0]
            log = log + values[1]
        }
    }

    fun testMultipleConcatDefect5() {
        var logStatement = ""
        val values = listOf("tic", "tac", "toe")
        logStatement = logStatement + values[0]
        logStatement += values[1] // bad 69
    }

    fun testMultipleConcatCorrect5() {
        var logStatement = ""
        val values = listOf("tic", "tac", "toe")
        logStatement = logStatement + values[0] + values[1]
    }

    fun testMultipleConcatDefect6() {
        var log = someString();
        var i = 0
        while (i++ < 3) {
            val values = listOf(1, 2, 3)
            log = log + values[0]
            log = log + values[1] //bad 84
        }
    }

    fun testMultipleConcatCorrect6() {
        var log = someInt("");
        var i = 0
        while (i++ < 3) {
            val values = listOf(1, 2, 3)
            log = log + values[0]
            log = log + values[1]
        }
    }

    fun testMultipleConcatDefect7() {
        var logStatement: String = someUnknown();
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0]
        logStatement += values[1] // bad 102
    }

    fun testMultipleConcatCorrect7() {
        var logStatement: String = someUnknown();
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0] + values[1]
    }

    fun testMultipleConcatDefect8() {
        var logStatement = "{"
        val values = listOf("tic", "tac", "toe")
        logStatement += "$values[0], "
        logStatement += "$values[1]}" // bad 115
    }

    fun testMultipleConcatCorrect8() {
        var logStatement = "{"
        val values = listOf("tic", "tac", "toe")
        logStatement += "$values[0], $values[1]}"
    }

    fun testMultipleConcatDefect9(first: String) {
        var logStatement = first;
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0]
        logStatement += values[1] // bad 128
    }

    fun testMultipleConcatCorrect9(first: Int) {
        var logStatement = first;
        val values = listOf(1, 2, 3)
        logStatement += values[0]
        logStatement += values[1]
    }

    fun testMultipleConcatDefect10() {
        var logStatement = someString();
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0]
        logStatement += values[1] // bad 142
    }

    fun testMultipleConcatCorrect10() {
        var logStatement = someInt("");
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0]
        logStatement += values[1]
    }

    fun testMultipleConcatDefect11() {
        var logStatement = someString(someString());
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0]
        logStatement += values[1] // bad 156
    }

    fun testMultipleConcatCorrect11() {
        var logStatement = someInt(someString());
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0]
        logStatement += values[1]
    }

    fun testMultipleConcatDefect12() {
        var logStatement = someString("");
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0]
        logStatement += values[1] // bad 170
    }

    fun testMultipleConcatCorrect12() {
        var logStatement = someString("");
        val values = listOf("tic", "tac", "toe")
        logStatement += values[0] + values[1]
    }

    private fun someString(): String {
        return "";
    }

    private fun someString(str: String): String {
        return str;
    }

    private fun someInt(str: String): Int {
        return 0;
    }
}

class AvoidMultipleConcatStatementsFalsePos {
    private fun falsePos(): Map<String, String> {
            val key = "key:"
            return mutableMapOf<String, String>().apply {
                this[key + "A"] = "valA"
                this[key + "B"] = "valB" // <-- false positive
            }
    }
}

class AvoidMultipleConcatStatementsNonStringPlus {
    fun numericPlus() {
        var sum = 0
        val a = 1
        val b = 2
        sum += a
        sum += b
        sum = sum + 3
        sum = sum + 4
    }
    fun listPlus() {
        var list = listOf(1, 2)
        list = list + listOf(3)
        list = list + listOf(4)
    }
    fun arrayPlus() {
        var arr = arrayOf(1)
        arr = arr + arrayOf(2)
        arr = arr + arrayOf(3)
    }
    fun setPlus() {
        var set = setOf(1)
        set = set + 2
        set = set + 3
    }
    fun mapPlus() {
        var m = mapOf("a" to 1)
        m = m + mapOf("b" to 2)
        m = m + mapOf("c" to 3)
    }
}

class AvoidMultipleConcatStatementsCharPlus {
    fun charPlus() {
        var c = 'a'
        c = (c + 1)
        c = (c + 1)
    }
}

class AvoidMultipleConcatStatementsPrimitiveArrayPlus {
    fun intArrayPlus() {
        var arr = intArrayOf(1)
        arr = arr + 2
        arr = arr + intArrayOf(3)
    }
}

class AvoidMultipleConcatStatementsSequencePlus {
    fun seqPlus() {
        var s = sequenceOf(1)
        s = s + 2
        s = s + 3
    }
}

class AvoidMultipleConcatStatementsPlusAssign {
    fun mutablePlusAssign() {
        val ml = mutableListOf(1)
        ml += 2
        ml += 3
        val ms = mutableSetOf(1)
        ms += 2
        ms += 3
        val mm = mutableMapOf("a" to 1)
        mm += ("b" to 2)
        mm += ("c" to 3)
    }
}

class AvoidMultipleConcatStatementsMapPairPlus {
    fun mapPairPlus() {
        var m = mapOf("a" to 1)
        m = m + ("b" to 2)
        m = m + ("c" to 3)
    }
}

class AvoidMultipleConcatStatementsStringPropertyPlus {
    var prop: String = ""
    fun bad() {
        prop += "A"
        prop += "B" // bad (not reported by current rule)
    }
}

class AvoidMultipleConcatStatementsNullableStringPlus {
    fun bad(s1: String?, s2: String?) {
        var log = ""
        log += (s1 ?: "")
        log += (s2 ?: "") // bad
    }
}

class AvoidMultipleConcatStatementsCharToStringPlus {
    fun bad() {
        var s = ""
        s += 'a'
        s += 'b' // bad
    }
}

class AvoidMultipleConcatStatementsApplyPlus {
    var msg: String = ""
    fun bad() {
        this.apply {
            msg += "A"
            msg += "B" // bad (not reported by current rule)
        }
    }
}
